  <div class="header">
    <h1>Global Water Stress: Multi-Indicator Analysis</h1>
    <p>10 Countries | 2023 Estimates | Sources: FAO AQUASTAT, WRI Aqueduct</p>
  </div>

  <div class="dashboard">
    <div class="card">
      <div class="card-title">Supply-to-Demand Ratio by Country</div>
      <canvas id="supplyDemandChart"></canvas>
      <div class="legend-inline">
        <div class="legend-item">
          <div class="threshold-line"></div>
          <span class="threshold-label">CRITICAL THRESHOLD (1.0)</span>
        </div>
      </div>
    </div>

    <div class="card">
      <div class="card-title">Per Capita Freshwater Availability</div>
      <canvas id="perCapitaChart"></canvas>
      <div class="legend-inline">
        <div class="legend-item">
          <div class="legend-dot" style="background: #059669"></div>
          <span>Below 1,000 m³/person/year (scarcity threshold)</span>
        </div>
      </div>
    </div>

    <div class="card">
      <div class="card-title">Groundwater Extraction vs Recharge Ratio</div>
      <canvas id="groundwaterChart"></canvas>
      <div class="legend-inline">
        <div class="legend-item">
          <div class="threshold-line"></div>
          <span class="threshold-label">OVERDRAFT THRESHOLD (1.0)</span>
        </div>
      </div>
    </div>

    <div class="card">
      <div class="card-title">Decadal Precipitation Trends (1990s–2010s)</div>
      <canvas id="precipitationChart"></canvas>
    </div>
  </div>

  <script>
    const colors = {
      critical: '#dc2626',
      warning: '#d97706',
      safe: '#059669',
      info: '#0891b2',
      primary: '#1e3a5f',
      muted: '#94a3b8'
    };

    Chart.defaults.font.family = "'IBM Plex Sans', system-ui, sans-serif";
    Chart.defaults.font.size = 11;

    // Supply-Demand Ratio Chart
    const sdData = [
      { country: 'Canada', ratio: 6.12 },
      { country: 'Brazil', ratio: 4.35 },
      { country: 'USA', ratio: 1.82 },
      { country: 'Australia', ratio: 1.55 },
      { country: 'Mexico', ratio: 1.08 },
      { country: 'South Africa', ratio: 0.91 },
      { country: 'India', ratio: 0.72 },
      { country: 'Pakistan', ratio: 0.65 },
      { country: 'Egypt', ratio: 0.48 },
      { country: 'Saudi Arabia', ratio: 0.31 }
    ];

    new Chart(document.getElementById('supplyDemandChart'), {
      type: 'bar',
      data: {
        labels: sdData.map(d => d.country),
        datasets: [{
          data: sdData.map(d => d.ratio),
          backgroundColor: sdData.map(d => d.ratio < 1 ? colors.critical : d.ratio < 1.5 ? colors.warning : colors.safe),
          borderRadius: 2,
          barThickness: 18
        }]
      },
      options: {
        indexAxis: 'y',
        plugins: {
          legend: { display: false },
          annotation: {
            annotations: {
              line1: {
                type: 'line',
                xMin: 1,
                xMax: 1,
                borderColor: colors.critical,
                borderWidth: 1.5,
                borderDash: [4, 3],
                label: { display: false }
              }
            }
          }
        },
        scales: {
          x: {
            beginAtZero: true,
            grid: { color: '#e5e7eb' },
            ticks: {
              callback: v => v.toFixed(1),
              font: { family: "'IBM Plex Mono', monospace", size: 9 }
            },
            title: { display: true, text: 'Ratio (supply ÷ demand)', font: { size: 10, weight: '500' } }
          },
          y: {
            grid: { display: false },
            ticks: { font: { size: 10 } }
          }
        }
      },
      plugins: [{
        id: 'thresholdLine',
        afterDraw: (chart) => {
          const xScale = chart.scales.x;
          const yScale = chart.scales.y;
          const x = xScale.getPixelForValue(1);
          chart.ctx.strokeStyle = colors.critical;
          chart.ctx.setLineDash([4, 3]);
          chart.ctx.lineWidth = 1.5;
          chart.ctx.beginPath();
          chart.ctx.moveTo(x, yScale.top);
          chart.ctx.lineTo(x, yScale.bottom);
          chart.ctx.stroke();
          chart.ctx.setLineDash([]);
          chart.ctx.fillStyle = colors.critical;
          chart.ctx.font = "600 9px 'IBM Plex Mono'";
          chart.ctx.fillText('1.0', x + 3, yScale.bottom - 4);
        }
      }]
    });

    // Per Capita Freshwater Chart
    const pcData = [
      { country: 'Canada', m3: 80620 },
      { country: 'Brazil', m3: 27436 },
      { country: 'Australia', m3: 20180 },
      { country: 'USA', m3: 8844 },
      { country: 'Mexico', m3: 3656 },
      { country: 'India', m3: 1486 },
      { country: 'South Africa', m3: 830 },
      { country: 'Pakistan', m3: 934 },
      { country: 'Egypt', m3: 570 },
      { country: 'Saudi Arabia', m3: 84 }
    ];

    new Chart(document.getElementById('perCapitaChart'), {
      type: 'bar',
      data: {
        labels: pcData.map(d => d.country),
        datasets: [{
          data: pcData.map(d => d.m3),
          backgroundColor: pcData.map(d => d.m3 < 1000 ? colors.critical : d.m3 < 2000 ? colors.warning : colors.safe),
          borderRadius: 2,
          barThickness: 18
        }]
      },
      options: {
        indexAxis: 'y',
        plugins: {
          legend: { display: false }
        },
        scales: {
          x: {
            type: 'logarithmic',
            beginAtZero: true,
            grid: { color: '#e5e7eb' },
            ticks: {
              callback: v => v >= 1000 ? (v/1000).toFixed(0) + 'k' : v,
              font: { family: "'IBM Plex Mono', monospace", size: 9 }
            },
            title: { display: true, text: 'm³/person/year (log scale)', font: { size: 10, weight: '500' } }
          },
          y: {
            grid: { display: false },
            ticks: { font: { size: 10 } }
          }
        }
      },
      plugins: [{
        id: 'scarcityLine',
        afterDraw: (chart) => {
          const xScale = chart.scales.x;
          const yScale = chart.scales.y;
          const x = xScale.getPixelForValue(1000);
          chart.ctx.strokeStyle = colors.warning;
          chart.ctx.setLineDash([4, 3]);
          chart.ctx.lineWidth = 1.5;
          chart.ctx.beginPath();
          chart.ctx.moveTo(x, yScale.top);
          chart.ctx.lineTo(x, yScale.bottom);
          chart.ctx.stroke();
          chart.ctx.setLineDash([]);
          chart.ctx.fillStyle = colors.warning;
          chart.ctx.font = "600 9px 'IBM Plex Mono'";
          chart.ctx.fillText('1k', x + 3, yScale.bottom - 4);
        }
      }]
    });

    // Groundwater Extraction Ratio Chart
    const gwData = [
      { country: 'Saudi Arabia', ratio: 5.66 },
      { country: 'Egypt', ratio: 1.63 },
      { country: 'Pakistan', ratio: 1.16 },
      { country: 'South Africa', ratio: 0.98 },
      { country: 'USA', ratio: 0.88 },
      { country: 'Mexico', ratio: 0.75 },
      { country: 'India', ratio: 0.58 },
      { country: 'Australia', ratio: 0.23 },
      { country: 'Brazil', ratio: 0.10 },
      { country: 'Canada', ratio: 0.05 }
    ];

    new Chart(document.getElementById('groundwaterChart'), {
      type: 'bar',
      data: {
        labels: gwData.map(d => d.country),
        datasets: [{
          data: gwData.map(d => d.ratio),
          backgroundColor: gwData.map(d => d.ratio > 1 ? colors.critical : d.ratio > 0.7 ? colors.warning : colors.safe),
          borderRadius: 2,
          barThickness: 18
        }]
      },
      options: {
        indexAxis: 'y',
        plugins: {
          legend: { display: false }
        },
        scales: {
          x: {
            beginAtZero: true,
            grid: { color: '#e5e7eb' },
            ticks: {
              callback: v => v.toFixed(1),
              font: { family: "'IBM Plex Mono', monospace", size: 9 }
            },
            title: { display: true, text: 'Extraction ÷ Recharge Ratio', font: { size: 10, weight: '500' } }
          },
          y: {
            grid: { display: false },
            ticks: { font: { size: 10 } }
          }
        }
      },
      plugins: [{
        id: 'overdraftLine',
        afterDraw: (chart) => {
          const xScale = chart.scales.x;
          const yScale = chart.scales.y;
          const x = xScale.getPixelForValue(1);
          chart.ctx.strokeStyle = colors.critical;
          chart.ctx.setLineDash([4, 3]);
          chart.ctx.lineWidth = 1.5;
          chart.ctx.beginPath();
          chart.ctx.moveTo(x, yScale.top);
          chart.ctx.lineTo(x, yScale.bottom);
          chart.ctx.stroke();
          chart.ctx.setLineDash([]);
          chart.ctx.fillStyle = colors.critical;
          chart.ctx.font = "600 9px 'IBM Plex Mono'";
          chart.ctx.fillText('1.0', x + 3, yScale.bottom - 4);
        }
      }]
    });

    // Precipitation Trends Chart
    const precipData = {
      labels: ['India', 'Pakistan', 'Egypt', 'Saudi Arabia', 'Mexico', 'South Africa', 'Australia', 'USA', 'Brazil', 'Canada'],
      decades: ['1990s', '2000s', '2010s'],
      colors: {
        decreasing: ['#dc2626', '#ef4444', '#f87171'],
        stable: ['#d97706', '#f59e0b', '#fbbf24'],
        increasing: ['#059669', '#10b981', '#34d399']
      }
    };

    const precipValues = {
      'India': [1120, 1095, 1078],
      'Pakistan': [396, 378, 355],
      'Egypt': [52, 47, 41],
      'Saudi Arabia': [98, 89, 78],
      'Mexico': [758, 742, 725],
      'South Africa': [498, 475, 452],
      'Australia': [465, 490, 478],
      'USA': [767, 780, 798],
      'Brazil': [1761, 1748, 1720],
      'Canada': [537, 548, 562]
    };

    const getTrendDirection = (values) => {
      const change = values[2] - values[0];
      if (change < -20) return 'decreasing';
      if (change > 20) return 'increasing';
      return 'stable';
    };

    new Chart(document.getElementById('precipitationChart'), {
      type: 'line',
      data: {
        labels: precipData.labels,
        datasets: [
          { label: '1990s', data: Object.values(precipValues).map(v => v[0]), borderColor: '#1e3a5f', backgroundColor: 'transparent', tension: 0.3, pointRadius: 3 },
          { label: '2000s', data: Object.values(precipValues).map(v => v[1]), borderColor: '#0891b2', backgroundColor: 'transparent', tension: 0.3, pointRadius: 3 },
          { label: '2010s', data: Object.values(precipValues).map(v => v[2]), borderColor: '#7dd3fc', backgroundColor: 'transparent', tension: 0.3, pointRadius: 3 }
        ]
      },
      options: {
        plugins: {
          legend: {
            position: 'bottom',
            labels: { boxWidth: 12, padding: 15, font: { family: "'IBM Plex Mono', monospace", size: 9 } }
          }
        },
        scales: {
          x: {
            grid: { color: '#e5e7eb' },
            ticks: { font: { size: 10 } }
          },
          y: {
            grid: { color: '#e5e7eb' },
            ticks: {
              callback: v => v + ' mm',
              font: { family: "'IBM Plex Mono', monospace", size: 9 }
            },
            title: { display: true, text: 'Mean Annual Precipitation', font: { size: 10, weight: '500' } }
          }
        }
      }
    });
  </script>
</body>
